declare(strict_types=1);require_once __DIR__.'/estimate_common.php';require_once __DIR__.'/production_report_common.php';$user=billing_require_admin();production_require_method('GET');$id=(int)($_GET['estimate_id']??0);$db=production_db();$s=$db->prepare("SELECT * FROM qbook_estimates WHERE id=? AND status<>'DRAFT'");$s->execute([$id]);$e=$s->fetch();if(!$e)qbook_json(['ok'=>false,'error'=>'SENT_ESTIMATE_NOT_FOUND'],404);estimate_require_sent_snapshots($e);$l=$db->prepare('SELECT * FROM qbook_estimate_lines WHERE estimate_id=? ORDER BY line_no');$l->execute([$id]);$lines=$l->fetchAll();try{$cache=production_report_cache_directory();$logo=production_report_normalize_png((string)file_get_contents(__DIR__.'/assets/ceh_logo.png'));if(!defined('K_PATH_CACHE'))define('K_PATH_CACHE',$cache);require_once __DIR__.'/vendor/tcpdf/tcpdf.php';$pdf=new TCPDF('P','mm','A4',true,'UTF-8',false);$pdf->SetPrintHeader(false);$pdf->SetPrintFooter(false);$pdf->SetMargins(15,14,15);$pdf->SetAutoPageBreak(true,18);$pdf->AddPage();$pdf->Image('@'.$logo,15,12,58,0,'PNG');$pdf->SetXY(80,12);$pdf->SetFont('dejavusans','B',11);$pdf->MultiCell(115,6,$e['company_legal_name_snapshot'],0,'R');$pdf->SetX(80);$pdf->SetFont('dejavusans','',8);$pdf->MultiCell(115,4.5,$e['company_address_snapshot'],0,'R');$pdf->SetX(80);$pdf->MultiCell(115,4.5,'TIN: '.$e['tax_identifier_snapshot'],0,'R');$ref=billing_ref('ESTIMATE',$e['reference_no']);$money=static fn($v):string=>'₦'.number_format((float)$v,2);$pdf->Ln(8);$pdf->SetFont('dejavusans','B',22);$pdf->Cell(100,10,'ESTIMATE');$pdf->SetFont('dejavusans','B',10);$pdf->Cell(80,10,$ref,0,1,'R');foreach([['CLIENT',$e['client_name_snapshot']],['ESTIMATE DATE',(new DateTimeImmutable($e['estimate_date']))->format('d-m-Y')],['VALID UNTIL',(new DateTimeImmutable($e['valid_until']))->format('d-m-Y')],['STATUS',$e['status']]]as$m){$pdf->SetFont('dejavusans','B',8);$pdf->Cell(40,6,$m[0]);$pdf->SetFont('dejavusans','',9);$pdf->Cell(140,6,(string)$m[1],0,1);}$pdf->Ln(5);$pdf->SetFont('dejavusans','B',8);foreach(['DESCRIPTION'=>75,'QTY'=>25,'RATE'=>35,'NET'=>30,'VAT'=>25]as$h=>$w)$pdf->Cell($w,8,$h,1,0,$h==='DESCRIPTION'?'L':'R',true);$pdf->Ln();foreach($lines as$x){$desc=$x['description'].($x['project_snapshot']?"\nProject: ".$x['project_snapshot']:'');$h=max(10,$pdf->getStringHeight(75,$desc)+3);$pdf->SetFont('dejavusans','',8);$pdf->MultiCell(75,$h,$desc,1,'L',false,0);$pdf->MultiCell(25,$h,$x['quantity']===null?'—':number_format((float)$x['quantity'],2).' '.($x['unit_name']?:'unit'),1,'R',false,0);$pdf->MultiCell(35,$h,$x['unit_price']===null?'—':$money($x['unit_price']),1,'R',false,0);$pdf->MultiCell(30,$h,$money($x['net_amount']),1,'R',false,0);$pdf->MultiCell(25,$h,$money($x['vat_amount']),1,'R',false,1);}$pdf->Ln(6);foreach([['Net',$e['net_amount']],['VAT '.billing_format_percent($e['vat_rate_snapshot']??0),$e['vat_amount']],['TOTAL',$e['total_amount']]]as$row){$pdf->SetX(117);$pdf->SetFont('dejavusans',$row[0]==='TOTAL'?'B':'',10);$pdf->Cell(40,8,$row[0]);$pdf->Cell(38,8,$money($row[1]),0,1,'R');}$pdf->Ln(6);$pdf->SetFont('dejavusans','B',9);$pdf->Cell(0,6,'TERMS / NOTES',0,1);$pdf->SetFont('dejavusans','',8.5);$pdf->MultiCell(180,5,trim((string)$e['terms_snapshot']."\n".(string)$e['notes']));$pdf->Ln(5);$pdf->SetFont('dejavusans','I',8);$pdf->MultiCell(180,5,'This Estimate is a non-accounting commercial document. It is not an invoice or proof of payment.');$bytes=$pdf->Output($ref.'.pdf','S');production_report_cleanup_cache_directory($cache);production_discard_output();header('Content-Type: application/pdf');header('Content-Length: '.strlen($bytes));header('Content-Disposition: attachment; filename="'.$ref.'.pdf"');header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');echo$bytes;exit;}catch(Throwable$ex){if(isset($cache))production_report_cleanup_cache_directory($cache);error_log('CEH Estimate PDF failed type='.get_class($ex));qbook_json(['ok'=>false,'error'=>'ESTIMATE_PDF_FAILED'],500);}
